var i=157;var a=[{id:`cooking-157-01`,theoryId:157,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why can adding too much water at once ruin a hummus texture?`,ua:`Чому додавання забагато води за раз може зіпсувати текстуру хумусу?`},explanation:{en:`Add liquids incrementally and assess texture after blending.`,ua:`Додавайте рідину поступово та оцінюйте текстуру після збивання.`},options:[{id:`a`,text:{en:`It dilutes the suspended solids and makes the spread runny`,ua:`Вода розбавляє тверді частинки й робить намазку надто рідкою`}},{id:`b`,text:{en:`It immediately makes the spread sterile`,ua:`Вона миттєво стерилізує намазку`}},{id:`c`,text:{en:`It converts chickpeas into sugar`,ua:`Вона перетворює нут на цукор`}}],answer:{optionIds:[`a`]}},{id:`cooking-157-02`,theoryId:157,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`A cold mayonnaise made with raw unpasteurized eggs has no Salmonella concern.`,ua:`Холодний майонез із сирих непастеризованих яєць не має ризику сальмонели.`},explanation:{en:`Pasteurized eggs or an egg-free formula reduce risks in uncooked egg sauces.`,ua:`Пастеризовані яйця або рецепт без яєць зменшують ризик для соусів без термообробки.`},answer:{value:!1}},{id:`cooking-157-03`,theoryId:157,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match cold preparations to their primary texture system.`,ua:`Поєднайте холодні страви з основним механізмом текстури.`},explanation:{en:`Understanding the structure makes texture corrections more reliable.`,ua:`Розуміння структури допомагає надійніше виправляти текстуру.`},leftItems:[{id:`l1`,text:{en:`Mayonnaise`,ua:`Майонез`}},{id:`l2`,text:{en:`Hummus`,ua:`Хумус`}},{id:`l3`,text:{en:`Yogurt dip`,ua:`Йогуртовий дип`}}],rightItems:[{id:`r3`,text:{en:`Fermented dairy protein matrix`,ua:`Матриця ферментованих молочних білків`}},{id:`r2`,text:{en:`Chickpea particle paste`,ua:`Паста з частинок нуту`}},{id:`r1`,text:{en:`Oil-in-water emulsion`,ua:`Емульсія олії у воді`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-157-04`,theoryId:157,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A cold chickpea dip is too thick after chilling. What is a controlled correction?`,ua:`Холодний нутовий дип після охолодження надто густий. Як його виправити?`},explanation:{en:`Small additions preserve control of viscosity and seasoning.`,ua:`Малі порції рідини дозволяють контролювати в’язкість і смак.`},options:[{id:`a`,text:{en:`Leave it in the sun to loosen`,ua:`Залишити на сонці, щоб розрідити`}},{id:`b`,text:{en:`Add a little safe liquid, blend, then taste`,ua:`Додати трохи безпечної рідини, збити та скуштувати`}},{id:`c`,text:{en:`Add a whole litre of liquid instantly`,ua:`Одразу влити цілий літр рідини`}}],answer:{optionIds:[`b`]}},{id:`cooking-157-05`,theoryId:157,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which storage approach is unsafe for a yogurt dip?`,ua:`Який спосіб зберігання йогуртового дипу небезпечний?`},explanation:{en:`Perishable dairy dips require time-temperature control.`,ua:`Молочні дипи, що швидко псуються, потребують контролю часу та температури.`},options:[{id:`a`,text:{en:`Use clean serving utensils`,ua:`Користуватися чистими столовими приборами`}},{id:`b`,text:{en:`Leave it on a warm buffet table all afternoon`,ua:`Залишити на теплому фуршетному столі на весь день`}},{id:`c`,text:{en:`Keep it refrigerated`,ua:`Зберігати в холодильнику`}}],answer:{optionIds:[`b`]}}];var n={theoryId:157,exercises:a};export{n as default,a as exercises,i as theoryId};